import org.junit.jupiter.api.*;
import java.util.*;

class OrderServiceTest {
    private OrderService orderService;
    private List<Order> testOrders;  // fresh list for each test

    @BeforeEach
    void setUp() {
        orderService = new OrderService();
        testOrders = new ArrayList<>();  // new list every test
        testOrders.add(new Order(1L, "Laptop", 999.99));
        testOrders.add(new Order(2L, "Mouse", 29.99));
    }

    @AfterEach
    void tearDown() {
        testOrders.clear();  // cleanup to prevent memory leaks
        orderService = null;  // allow garbage collection
    }

    @Test
    void shouldCalculateTotalPrice() {
        var total = orderService.calculateTotal(testOrders);
        Assertions.assertEquals(1029.98, total, 0.01);
    }
}

import org.junit.jupiter.api.*;

@DisplayName("Tax Calculator Service")
class TaxCalculatorTest {
    private TaxCalculator calculator;

    @BeforeEach
    void setUp() {
        calculator = new TaxCalculator();
    }

    @Test
    @DisplayName("should return zero tax when salary is below threshold")
    void testBelowThreshold() {
        var tax = calculator.calculate(15000);
        Assertions.assertEquals(0.0, tax);
    }

    @Test
    @DisplayName("should apply 20% tax rate when salary is between 50k and 100k")
    void testMiddleBracket() {
        var tax = calculator.calculate(75000);
        Assertions.assertEquals(15000.0, tax);  // 20% of 75k
    }
}

