import org.junit.jupiter.api.*;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.*;
import org.mockito.junit.jupiter.MockitoExtension;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)  // enables @Mock and @InjectMocks
class OrderServiceTest {
    @Mock
    private OrderRepository orderRepository;  // Mockito creates a mock

    @InjectMocks
    private OrderService orderService;  // injects the mock into the service

    @Test
    void shouldReturnOrderById() {
        var order = new Order(1L, "Laptop");
        when(orderRepository.findById(1L)).thenReturn(order);  // stub behavior

        var result = orderService.getOrder(1L);
        Assertions.assertEquals("Laptop", result.getItem());
    }
}

import org.junit.jupiter.api.*;

@DisplayName("User Registration Service")
class UserRegistrationTest {
    private UserService userService;

    @BeforeEach
    void setUp() {
        userService = new UserService();  // runs before every test
    }

    @Nested
    @DisplayName("Email Validation")
    class EmailValidation {
        @Test
        @DisplayName("should reject duplicate email addresses")
        void testDuplicateEmail() {
            userService.register("john@example.com", "password123");
            Assertions.assertThrows(DuplicateEmailException.class, 
                () -> userService.register("john@example.com", "password456"));
        }

        @Test
        @DisplayName("should reject invalid email format")
        void testInvalidFormat() {
            Assertions.assertThrows(InvalidEmailException.class,
                () -> userService.register("not-an-email", "password123"));
        }
    }

    @Nested
    @DisplayName("Password Strength")
    class PasswordStrength {
        @Test
        @DisplayName("should require at least 8 characters")
        void testMinLength() {
            Assertions.assertThrows(WeakPasswordException.class,
                () -> userService.register("user@example.com", "short"));
        }
    }
}
